INSERT INTO public.debug_findings (finding_code, severity, module, component, route, description, expected, actual, reproduction, root_cause, fix, verification, status) VALUES
('F-001','HIGH','Settings','Admin name field','/settings','Saving the admin name on Settings did not change the name shown in the sidebar or Profile.','Name saved to the profile shown everywhere.','Name written to sign-in metadata only; profile kept the old name.','Settings → change name → Save → sidebar still shows old name.','Two sources of truth for the admin name (auth metadata vs profiles table).','Removed the duplicate field; Settings links to Profile, the single place to edit name and photo.','Browser test: Settings shows "Edit on Profile" link; Profile save updates sidebar.','VERIFIED'),
('F-002','MEDIUM','Settings','Password form','/settings','Settings password change had no confirmation field.','New password must be typed twice.','Single field — a typo could lock the admin out.','Settings → Password section.','Form built without confirm input.','Added confirm field, mismatch check and same-as-current check.','Browser test: mismatched passwords show "The new passwords don''t match." and nothing is changed.','VERIFIED'),
('F-003','HIGH','Pipeline','Report generation','scanAnalyze','A failed report save was ignored and the scan still showed as complete with no report.','Report failures recorded and visible.','Insert error silently discarded.','Code trace of scanAnalyzeCore report insert.','Return value of reports insert not checked.','Insert result checked; failure recorded as REPORT_ERROR in the Error Center, scan graded LOW quality and timeline shows FAILED.','Code review + typecheck. Cannot be triggered without a live scan (needs Google key).','FIXED'),
('F-004','HIGH','Pipeline','Scan status','scanFetch','A scan whose server stopped mid-way stayed "running" forever and blocked re-scans of the same link.','Stale scans time out and can be retried.','No timeout.','Kill the worker during a scan.','No stale-run sweep.','Scans running over 15 minutes are marked failed (TIMEOUT) and logged in the Error Center at the next scan.','Code review + typecheck; DB check found 0 stuck scans currently.','FIXED'),
('F-005','MEDIUM','Dashboard','Recent scans table','/dashboard','Business names and dates wrapped into 4 lines and the Status column was cut off at 1280px.','Readable table.','Cramped columns.','Open Dashboard at 1280px width.','No min-width / nowrap on columns.','Business column min-width and no-wrap dates.','Screenshot comparison before/after.','VERIFIED'),
('F-006','MEDIUM','Tracking','Scan lifecycle','pipeline','No per-stage history: impossible to see where a scan stopped or how long each stage took.','Every transition stored with time, message, duration and error.','Only a single stage field.','Open any report.','Missing tracking model.','New scan_events table; pipeline records CREATED → PROCESSING → BUSINESS_RESOLVED → RATING_RETRIEVED → REVIEWS_RETRIEVED → REVIEWS_ANALYZING → ANALYSIS_COMPLETED → REPORT_GENERATING → REPORT_READY → ACTION_AVAILABLE / FAILED. Timeline on each report; live activity on Dashboard.','Typecheck + UI renders; real events need a live scan (Google key).','FIXED'),
('F-007','MEDIUM','AI','Risk engine','analysis','A single model decided risk; flags could be returned without quoted evidence.','Explainable flags and a second opinion for high/medium.','One model, no evidence guard.','Code trace of analyzeReviews.','No verification step.','Evidence guard (no quote/signal → Requires review) and second-model verification (openai/gpt-5-mini); disagreement moves the review to Requires review, never upgrades.','Live AI test: genuine 1-star → normal; competitor promo with phone number → high, second model agreed; empty 1-star → requires review.','VERIFIED'),
('F-008','LOW','AI','Cost control','analysis','Re-scanning the same business re-sent identical reviews to the AI.','Reuse earlier analysis for identical text + version.','Always re-analyzed.','Scan the same business twice.','No hashing/caching.','SHA-256 content hash per review; cached result reused when text, rating, prompt version and app version match. Cached rows marked cached=true.','Hash stability unit test passed; end-to-end needs two live scans.','FIXED'),
('F-009','MEDIUM','API','Error mapping','/api/scan/:id','Missing scans returned BUSINESS_NOT_FOUND.','RESOURCE_NOT_FOUND for missing records.','Wrong code.','GET /api/scan/<unknown uuid>.','Generic NOT_FOUND mapped to business code.','Separate RESOURCE_NOT_FOUND (404).','Real request returns RESOURCE_NOT_FOUND 404.','VERIFIED'),
('F-010','LOW','API','Bulk scan','/api/scan/bulk','Bulk API created an empty batch even when the Google key was missing.','Reject before creating a batch.','Empty batch #1001 created.','POST /api/scan/bulk without key.','Key checked per URL only.','Key checked before batch creation.','Real request returns GOOGLE_API_NOT_CONFIGURED; no new batch.','VERIFIED'),
('F-011','LOW','API','CSV validation','/api/scan/bulk','Empty CSV reported "No valid Google Maps links found".','Clear empty-file message.','Misleading message.','POST an empty CSV.','No empty check.','Returns VALIDATION_ERROR "The list or CSV is empty".','Real request.','VERIFIED'),
('F-012','MEDIUM','Security','Auth settings','auth','Leaked-password protection was disabled.','Known-breached passwords rejected.','Disabled.','Security linter.','Default setting.','Enabled leaked-password protection; current password still required to change it.','Auth settings updated; linter re-run.','VERIFIED'),
('F-013','HIGH','Google','Places API pipeline','/scan','Real Google scan, rating accuracy and review storage cannot be verified.','Live scan with real data.','Google key not configured.','Run any scan.','GOOGLE_MAPS_API_KEY not set.','Waiting for the key. App shows GOOGLE_API_NOT_CONFIGURED clearly.','—','BLOCKED'),
('F-014','MEDIUM','RLS','Cross-account isolation','database','Second-account isolation test cannot be run because public sign-up is disabled and only one admin exists.','Account B cannot read account A data.','Not executable.','—','Single-admin design.','Policies verified: every user table scopes to auth.uid(); anonymous reads return nothing; forged user_id inserts and writes to development data are rejected.','Anon + forged-token tests passed.','BLOCKED'),
('F-015','LOW','Deployment','Docker','VPS','Docker image build not executed (no Docker in the build sandbox).','docker compose build succeeds.','Not executable here.','—','Environment limit.','Node server build was built and started successfully; Docker verified on first VPS run.','Node build + health endpoint passed.','BLOCKED');